const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // A large Area of Interest over the lower Indus River floodplain in Pakistan.
  const aoi = ee.Geometry.Polygon([
      [
        [67.3, 27.0],
        [69.5, 27.0],
        [69.5, 30.0],
        [67.3, 30.0],
        [67.3, 27.0]
      ]
  ]);

  const startDateBefore = '2022-07-01';
  const endDateBefore = '2022-07-15';
  const startDateAfter = '2022-08-28';
  const endDateAfter = '2022-09-15';

  // 2. Data Acquisition & Processing Functions
  const cloudMask = function(image) {
    const scl = image.select('SCL');
    // Keep clear land (4), water (6), and vegetated (5) pixels.
    // Mask out clouds (8,9,10), shadow (3), cirrus (11).
    const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6));
    return image.updateMask(mask);
  };

  const calculateWater = function(image) {
    // NDWI = (Green - NIR) / (Green + NIR)
    // Sentinel-2 bands: B3 = Green, B8 = NIR
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi');
    // A threshold of 0 is commonly used to identify water bodies.
    const water = ndwi.gt(0).rename('water');
    return image.addBands(water);
  };

  const getWaterImage = (startDate, endDate) => {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(aoi)
      .filterDate(startDate, endDate)
      .map(cloudMask);

    // Check if collection is empty
    if (collection.size().getInfo() === 0) {
        return null; // Return null to indicate no images
    }

    // Create a median composite and calculate water extent
    const image = collection.median();
    return calculateWater(image);
  };

  // 3. Image Creation & Validation
  const imageBefore = getWaterImage(startDateBefore, endDateBefore);
  const imageAfter = getWaterImage(startDateAfter, endDateAfter);

  if (!imageBefore || !imageAfter) {
    console.log(`Image count 'Before' (July 1-15 2022): ${imageBefore ? '>0' : '0'}`);
    console.log(`Image count 'After' (Aug 28-Sep 15 2022): ${imageAfter ? '>0' : '0'}`);
    console.log('No images found for one or both periods.');
    console.log('C1');
    return;
  }

  // 4. Calculation
  const scale = 1000; // Use a coarser scale to ensure calculation completes
  const reducer = ee.Reducer.sum().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const statsBefore = imageBefore.select(['water', 'B3']).reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const statsAfter = imageAfter.select(['water', 'B3']).reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const waterPixelsBefore = statsBefore.get('water_sum').getInfo();
  const validPixelsBefore = statsBefore.get('B3_count').getInfo();

  const waterPixelsAfter = statsAfter.get('water_sum').getInfo();
  const validPixelsAfter = statsAfter.get('B3_count').getInfo();

  // 5. Validation & Final Answer
  if (validPixelsBefore === null || validPixelsAfter === null || waterPixelsBefore === null || waterPixelsAfter === null) {
      console.log('Calculation resulted in null values.');
      console.log('C3');
      return;
  }

  if (validPixelsBefore === 0 || validPixelsAfter === 0) {
    console.log(`Valid pixels 'Before': ${validPixelsBefore}`);
    console.log(`Valid pixels 'After': ${validPixelsAfter}`);
    console.log('No valid pixels remained after cloud masking.');
    console.log('C2');
    return;
  }

  const waterAreaSqKmBefore = (waterPixelsBefore * scale * scale) / 1e6;
  const waterAreaSqKmAfter = (waterPixelsAfter * scale * scale) / 1e6;

  console.log(`Early July 2022 water area (km^2): ${waterAreaSqKmBefore.toFixed(2)}`);
  console.log(`Late Aug 2022 water area (km^2): ${waterAreaSqKmAfter.toFixed(2)}`);
  console.log(`Change in water area (km^2): ${(waterAreaSqKmAfter - waterAreaSqKmBefore).toFixed(2)}`);

  if (waterAreaSqKmAfter > waterAreaSqKmBefore) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
